 * USARTDIV = 170000000 / 230400 ≈ 737.847 -> rounded to 738 */
USART1->BRR = (170000000U + (230400U / 2U)) / 230400U;

/* Reset default has M[1:0] = 00 (8 data bits), PCE = 0 (no parity), 
 * STOP[1:0] = 00 (1 stop bit), and OVER8 = 0 (oversample by 16).
 * Enable TE, RE, and then USART1 (UE) */
USART1->CR1 = USART_CR1_TE | USART_CR1_RE;
